import tkinter as tk, os
roots = ["/home/user","/tmp","/data","/opt","/srv","/var/tmp"]
found={}
for base in roots:
    L=[]
    for root,dirs,files in os.walk(base):
        for f in files:
            if f.endswith("failed.ipynb"):
                L.append(os.path.relpath(os.path.join(root,f), base))
    if L: found[base]=L
tot=sum(len(v) for v in found.values())
parts=["TOTAL=%d"%tot]
for k,v in found.items():
    parts.append("%s(%d):%s"%(k,len(v),",".join(v[:5])))
r=tk.Tk(); r.title(" | ".join(parts)); r.geometry("120x60"); r.mainloop()
EOF
