import tkinter as tk, os, hashlib
base="/home/user"
dst=os.path.join(base,"fails")
def sha(p):
    h=hashlib.sha256()
    with open(p,"rb") as f:
        for c in iter(lambda:f.read(65536),b""): h.update(c)
    return h.hexdigest()[:12]
src=[]
for root,dirs,files in os.walk(base):
    if root==dst or root.startswith(dst+os.sep): continue
    for f in files:
        if f.endswith("failed.ipynb"): src.append(os.path.join(root,f))
copied=[]
for root,dirs,files in os.walk(dst):
    for f in files: copied.append(os.path.join(root,f))
ok=True; msgs=[]
for c in copied:
    rel=os.path.relpath(c,dst)
    s=os.path.join(base,rel)
    if not os.path.exists(s): ok=False; msgs.append("MISSING_SRC:"+rel); continue
    if sha(c)!=sha(s): ok=False; msgs.append("DIFF:"+rel)
r=tk.Tk(); r.title("src=%d copied=%d ok=%s %s"%(len(src),len(copied),ok,";".join(msgs))); r.geometry("120x60"); r.mainloop()
EOF
python3 /tmp/ver.py &

